GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def compute_model_placement(gpu_num, models):
    """Exactly enumerate small placements, otherwise greedily balance KVPR and improve it locally."""
    if gpu_num <= 0:
        raise ValueError("At least one GPU is required")
    if not models:
        return {i: [] for i in range(gpu_num)}

    # For small cases, evaluate the true objective for every assignment.  GPU
    # labels are interchangeable, so fixing the first model on GPU 0 is lossless.
    import itertools
    n = len(models)
    if gpu_num ** (n - 1) <= 100000:
        weights = [m.req_rate / m.slo for m in models]
        sizes = [m.model_size for m in models]
        best_value, best_assignment = float("inf"), None
        for tail in itertools.product(range(gpu_num), repeat=n - 1):
            assignment = (0,) + tail
            remaining = [GPU_MEM_SIZE] * gpu_num
            load = [0.0] * gpu_num
            for i, gpu in enumerate(assignment):
                remaining[gpu] -= sizes[i]
                if remaining[gpu] <= 0:
                    break
                load[gpu] += weights[i]
            else:
                value = max(load[i] / remaining[i] for i in range(gpu_num))
                if value < best_value:
                    best_value, best_assignment = value, assignment
        if best_assignment is not None:
            result = {i: [] for i in range(gpu_num)}
            for model, gpu in zip(models, best_assignment):
                result[gpu].append(model)
            return result

    # Different orders handle the tradeoff between preserving memory for large
    # models and spreading high request-pressure models more effectively.
    best = None
    orders = (
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / m.model_size, reverse=True),
    )
    for order in orders:
        candidate = {i: [] for i in range(gpu_num)}
        rem, loads = [GPU_MEM_SIZE] * gpu_num, [0.0] * gpu_num
        for model in order:
            weight, size = model.req_rate / model.slo, model.model_size
            gpu = min(
                (i for i in range(gpu_num) if rem[i] > size),
                key=lambda i: (loads[i] + weight) / (rem[i] - size),
                default=None,
            )
            if gpu is None:
                break
            candidate[gpu].append(model)
            rem[gpu] -= size
            loads[gpu] += weight
        else:
            score = max(loads[i] / rem[i] for i in range(gpu_num))
            if best is None or score < best[0]:
                best = score, candidate, rem, loads

    if best is None:
        raise ValueError("Unable to place all models")
    _, placement, remaining, load = best

    for _ in range(len(models)):
        pressure = [load[i] / remaining[i] if remaining[i] else float("inf")
                    for i in range(gpu_num)]
        best_value, best = max(pressure), None

        for source in range(gpu_num):
            for model in placement[source]:
                weight, size = model.req_rate / model.slo, model.model_size
                for dest in range(gpu_num):
                    if source == dest or remaining[dest] <= size:
                        continue
                    value = max(
                        (load[source] - weight) / (remaining[source] + size) if i == source else
                        (load[dest] + weight) / (remaining[dest] - size) if i == dest else pressure[i]
                        for i in range(gpu_num)
                    )
                    if value < best_value:
                        best_value, best = value, ("move", source, dest, model)

            # A joint relocation may improve the bottleneck even when either
            # individual relocation would be rejected by the strict search.
            for x_index, x in enumerate(placement[source]):
                wx, sx = x.req_rate / x.slo, x.model_size
                for y in placement[source][x_index + 1:]:
                    wy, sy = y.req_rate / y.slo, y.model_size
                    for dest in range(gpu_num):
                        if source == dest or remaining[dest] <= sx + sy:
                            continue
                        value = max(
                            (load[source] - wx - wy) / (remaining[source] + sx + sy)
                            if i == source else
                            (load[dest] + wx + wy) / (remaining[dest] - sx - sy)
                            if i == dest else pressure[i]
                            for i in range(gpu_num)
                        )
                        if value < best_value:
                            best_value, best = value, ("pair", source, dest, x, y)

        for a in range(gpu_num):
            for b in range(a + 1, gpu_num):
                for x in placement[a]:
                    for y in placement[b]:
                        wx, sx = x.req_rate / x.slo, x.model_size
                        wy, sy = y.req_rate / y.slo, y.model_size
                        ra, rb = remaining[a] + sx - sy, remaining[b] + sy - sx
                        if ra <= 0 or rb <= 0:
                            continue
                        value = max(
                            (load[a] - wx + wy) / ra if i == a else
                            (load[b] - wy + wx) / rb if i == b else pressure[i]
                            for i in range(gpu_num)
                        )
                        if value < best_value:
                            best_value, best = value, ("swap", a, b, x, y)

        if best is None:
            break
        if best[0] == "move":
            _, source, dest, model = best
            weight, size = model.req_rate / model.slo, model.model_size
            placement[source].remove(model)
            placement[dest].append(model)
            load[source] -= weight
            load[dest] += weight
            remaining[source] += size
            remaining[dest] -= size
        elif best[0] == "pair":
            _, source, dest, x, y = best
            wx, sx = x.req_rate / x.slo, x.model_size
            wy, sy = y.req_rate / y.slo, y.model_size
            placement[source].remove(x)
            placement[source].remove(y)
            placement[dest].extend((x, y))
            load[source] -= wx + wy
            load[dest] += wx + wy
            remaining[source] += sx + sy
            remaining[dest] -= sx + sy
        else:
            _, a, b, x, y = best
            wx, sx = x.req_rate / x.slo, x.model_size
            wy, sy = y.req_rate / y.slo, y.model_size
            placement[a].remove(x)
            placement[b].remove(y)
            placement[a].append(y)
            placement[b].append(x)
            load[a] += wy - wx
            load[b] += wx - wy
            remaining[a] += sx - sy
            remaining[b] += sy - sx

    return placement

# EVOLVE-BLOCK-END


